import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits around.

    x must be in 0..255 and k in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xA5, 0xFF):
        assert rotl8(x, 0) == x


def test_rotl8_known_values() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0xF0, 4) == 0x0F
    assert rotl8(0x3C, 2) == 0xF0
    assert rotl8(0xA5, 4) == 0x5A


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(0xFF, k) == 0xFF


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_matches_reference() -> None:
    for x in range(256):
        for k in range(8):
            expected = ((x << k) | (x >> (8 - k))) & 0xFF
            assert rotl8(x, k) == expected


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0b11000000, 2, 0b00000011),
        (0b01010101, 1, 0b10101010),
        (0b00010000, 3, 0b10000000),
        (0b00010000, 4, 0b00000001),
        (0b00010000, 5, 0b00000010),
    ],
)
def test_rotl8_parametrized(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected
